	if((e = getaddrinfo(host, port, &hints, &res))) {
		fprintf(stderr, "wt-client: getaddrinfo: %s\n",
			gai_strerror(e));
		exit(1);
	}
	sock = socket(res->ai_family, res->ai_socktype, res->ai_protocol);
	if(sock < 0) {
		fail("could not create socket");
	}
	if(connect(sock, res->ai_addr, res->ai_addrlen) < 0) {
		fail("could not connect");
	}
	freeaddrinfo(res);
	return sock;
}

static void negotiate_go(int sock, const char *exportname) {
	char init_passwd[8];
	uint64_t magic;
	uint16_t sflags;
	uint32_t cflags;
	uint32_t namelen;
	uint32_t optlen;
	uint32_t opt;
	uint32_t type;
	uint32_t len;
	uint16_t n_requests;
	struct {
		uint64_t magic;
		uint32_t opt;
		uint32_t len;
	} __attribute__((packed)) optreq;
	struct {
		uint64_t magic;
		uint32_t opt;
		uint32_t type;
		uint32_t len;
	} __attribute__((packed)) optrep;
	char scratch[4096];

	if(readit(sock, init_passwd, 8) < 0) {
		fail("could not read initial magic");
	}
	if(memcmp(init_passwd, INIT_PASSWD, 8) != 0) {
		fail("initial magic mismatch");
	}
	if(readit(sock, &magic, 8) < 0) {
		fail("could not read options magic");
	}
	magic = ntohll(magic);
	if(magic != 0x49484156454F5054LL) {
		fail("options magic mismatch");
	}
	if(readit(sock, &sflags, 2) < 0) {
		fail("could not read handshake flags");
	}
	cflags = htonl(NBD_FLAG_C_FIXED_NEWSTYLE | NBD_FLAG_C_NO_ZEROES);
	if(writeit(sock, &cflags, 4) < 0) {
		fail("could not send client flags");
	}

	namelen = strlen(exportname);
	n_requests = 0;
	optlen = namelen + sizeof(namelen) + sizeof(n_requests);
	optreq.magic = htonll(0x49484156454F5054LL);
	optreq.opt = htonl(NBD_OPT_GO);
	optreq.len = htonl(optlen);
	namelen = htonl(namelen);
	n_requests = htons(n_requests);
	if(writeit(sock, &optreq, sizeof(optreq)) < 0) {
		fail("could not send option request");
	}
	if(writeit(sock, &namelen, sizeof(namelen)) < 0) {
		fail("could not send export name length");
	}
	if(writeit(sock, exportname, ntohl(namelen)) < 0) {
		fail("could not send export name");
	}
	if(writeit(sock, &n_requests, sizeof(n_requests)) < 0) {
		fail("could not send info request count");
	}

	while(1) {
		if(readit(sock, &optrep, sizeof(optrep)) < 0) {
			fail("could not read option reply");
		}
		if(ntohll(optrep.magic) != NBD_OPT_REPLY_MAGIC) {
			fail("option reply magic mismatch");
		}
		type = ntohl(optrep.type);
		len = ntohl(optrep.len);
		if(len > sizeof(scratch)) {
			fail("option reply too long");
		}
		if(readit(sock, scratch, len) < 0) {
			fail("could not read option reply data");
		}
		if(type & NBD_REP_FLAG_ERROR) {
			fail("server sent error reply to NBD_OPT_GO");
		}
		if(type == NBD_REP_ACK) {
			opt = ntohl(optrep.opt);
			if(opt != NBD_OPT_GO) {
				fail("ACK for the wrong option");
			}
			return;
		}
	}
}

static int do_io(int sock, uint32_t cmd, uint64_t from, unsigned char *buf,
		 uint32_t len, uint32_t *rerror) {
	struct nbd_request req;
	struct nbd_reply rep;
	static uint64_t cookie = 0;

	req.magic = htonl(NBD_REQUEST_MAGIC);
	req.type = htonl(cmd);
	req.cookie = htonll(++cookie);
	req.from = htonll(from);
	req.len = htonl(len);
	if(writeit(sock, &req, sizeof(req)) < 0) {
		return -1;
	}
	if(cmd == NBD_CMD_WRITE) {
		if(writeit(sock, buf, len) < 0) {
			return -1;
		}
	}
	if(readit(sock, &rep, sizeof(rep)) < 0) {
		return -1;
	}
	if(rep.magic != htonl(NBD_REPLY_MAGIC)) {
		fail("reply magic mismatch");
	}
	if(rep.cookie != req.cookie) {
		fail("cookie mismatch");
	}
	*rerror = ntohl(rep.error);
	if(*rerror != 0) {
		return 0;
	}
	if(cmd == NBD_CMD_READ) {
		if(readit(sock, buf, len) < 0) {
			return -1;
		}
	}
	return 0;
}

static void disconnect(int sock) {
	struct nbd_request req;

	req.magic = htonl(NBD_REQUEST_MAGIC);
	req.type = htonl(NBD_CMD_DISC);
	req.cookie = 0;
	req.from = 0;
	req.len = 0;
	if(writeit(sock, &req, sizeof(req)) < 0) {
		fail("disconnect failed");
	}
	close(sock);
}

static int do_wp(const char *host, const char *port, const char *export) {
	static unsigned char buf[4096];
	uint32_t error;
	int sock;

	sock = connect_tcp(host, port);
	negotiate_go(sock, export);

	memset(buf, 0x5A, sizeof(buf));
	if(do_io(sock, NBD_CMD_WRITE, 4096, buf, sizeof(buf), &error) < 0) {
		fail("write failed");
	}
	if(error != 0) {
		fprintf(stderr, "wt-client: write refused: error %u\n",
			error);
		return 1;
	}
	/* clean page: must be refused while the server is still waiting
	 * for the master file */
	if(do_io(sock, NBD_CMD_READ, 0, buf, sizeof(buf), &error) < 0) {
		fail("read request failed");
	}
	if(error == 0) {
		fprintf(stderr, "wt-client: read of clean page succeeded"
			" while waitfile export has no master file yet\n");
		return 1;
	}
	disconnect(sock);
	printf("wt-client: wp OK (write accepted, clean-page read refused)\n");
	return 0;
}

static int do_rp(const char *host, const char *port, const char *export) {
	static unsigned char buf[4096];
	uint32_t error;
	int sock;
	unsigned int i;

	sock = connect_tcp(host, port);
	negotiate_go(sock, export);

	if(do_io(sock, NBD_CMD_READ, 4096, buf, sizeof(buf), &error) < 0) {
		fail("read of written page failed");
	}
	if(error != 0) {
		fprintf(stderr, "wt-client: read of written page returned"
			" error %u after merge\n", error);
		return 1;
	}
	for(i = 0; i < sizeof(buf); i++) {
		if(buf[i] != 0x5A) {
			fprintf(stderr, "wt-client: merged page has wrong"
				" data at byte %u\n", i);
			return 1;
		}
	}
	if(do_io(sock, NBD_CMD_READ, 0, buf, sizeof(buf), &error) < 0) {
		fail("read of clean page failed");
	}
	if(error != 0) {
		fprintf(stderr, "wt-client: read of clean page returned"
			" error %u after merge\n", error);
		return 1;
	}
	for(i = 0; i < sizeof(buf); i++) {
		if(buf[i] != 0x00) {
			fprintf(stderr, "wt-client: master page has wrong"
				" data at byte %u\n", i);
			return 1;
		}
	}
	disconnect(sock);
	printf("wt-client: rp OK (merged page and master page read back)\n");
	return 0;
}

int main(int argc, char *argv[]) {
	if(argc != 5) {
		fprintf(stderr, "usage: wt-client wp|rp <host> <port>"
			" <export>\n");
		return 1;
	}
	if(strcmp(argv[1], "wp") == 0) {
		return do_wp(argv[2], argv[3], argv[4]);
	}
	if(strcmp(argv[1], "rp") == 0) {
		return do_rp(argv[2], argv[3], argv[4]);
	}
	fprintf(stderr, "wt-client: invalid mode\n");
	return 1;
}

